arguments.content:
"""The warehouse's own records of its job runs and transactions (`_ops/`, docs/WAREHOUSE.md).

A transaction is committed if and only if its outcome in `commits.jsonl` is `commit`, at its `at`. The scheduler log
says what each transaction wrote (the order windows a loader selected, the statements a migration ran, the start of
each crm_sync run).
"""
import json
import os
import re

import pandas as pd

_LINE = re.compile(r"^(\S+) (\S+) run=(\S+) (.*)$")
_SELECT = re.compile(r"selected orders where ordered_at >= (\S+) and ordered_at < (\S+): (\d+) rows; "
                     r"sent txn (\d+) to commit into (\S+)")
_COPY = re.compile(r"copied table (\S+) where ordered_at < (\S+): (\d+) rows; sent txn (\d+) to commit into (\S+)")
_STATEMENT = re.compile(r"statement: (.*?);?\s*$")
_SENT = re.compile(r"sent txn (\d+) to commit")
_RENAME = re.compile(r"ALTER TABLE (\S+) RENAME TO (\S+)", re.I)
_DROP = re.compile(r"DROP TABLE (?:IF EXISTS )?(\S+)", re.I)
_DQ = re.compile(r"order day (\d{4}-\d{2}-\d{2}): (.*)$")


def ts(s):
    return pd.Timestamp(s).tz_convert("UTC") if pd.Timestamp(s).tzinfo else pd.Timestamp(s, tz="UTC")


class Ops:
    def __init__(self, data_dir):
        d = os.path.join(data_dir, "_ops")
        self.commits = {}
        with open(os.path.join(d, "commits.jsonl")) as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                r = json.loads(line)
                self.commits[int(r["txn"])] = r
        self.selects = []      # dict(job, a, b, n, txn, into)
        self.copies = []       # dict(source, before, n, txn, into)
        self.ddl = []          # dict(statements, txn)
        self.crm_starts = {}   # run -> start time
        self.crm_txn = {}      # run -> txn
        self.dq_bad_days = set()
        pending = {}           # (job, run) -> statements not yet sent
        with open(os.path.join(d, "scheduler.log")) as f:
            for line in f:
                m = _LINE.match(line.rstrip("\n"))
                if not m:
                    continue
                t, job, run, rest = m.groups()
                if job == "crm_sync":
                    if "state=running" in rest:
                        self.crm_starts[run] = ts(t)
                    s = _SENT.search(rest)
                    if s:
                        self.crm_txn[run] = int(s.group(1))
                s = _SELECT.search(rest)
                if s:
                    a, b, n, txn, into = s.groups()
                    self.selects.append(dict(job=job, a=ts(a), b=ts(b), n=int(n), txn=int(txn), into=into))
                    continue
                s = _COPY.search(rest)
                if s:
                    src, before, n, txn, into = s.groups()
                    self.copies.append(dict(source=src, before=ts(before), n=int(n), txn=int(txn), into=into))
                    continue
                s = _DQ.search(rest)
                if s:
                    if not s.group(2).rstrip().endswith("rows and values equal"):
                        self.dq_bad_days.add(s.group(1))
                    continue
                s = _STATEMENT.search(rest)
                if s:
                    pending.setdefault((job, run), []).append(s.group(1))
                    continue
                s = _SENT.search(rest)
                if s and (job, run) in pending:
                    self.ddl.append(dict(statements=pending.pop((job, run)), txn=int(s.group(1))))

    def committed_at(self, txn):
        """Commit time of a transaction, None if it was not committed."""
        r = self.commits.get(txn)
        if r is None or r.get("outcome") != "commit":
            return None
        return ts(r["at"])

    def crm_syncs(self):
        """(start, commit) of every committed crm_sync run, by commit time."""
        out = []
        for run, txn in self.crm_txn.items():
            at = self.committed_at(txn)
            if at is not None and run in self.crm_starts:
                out.append((self.crm_starts[run], at))
        return sorted(out, key=lambda x: x[1])

    def name_history(self, name="orders"):
        """Eras of the physical table read under `name`: list of (start, end, physical id).

        Physical tables are identified by the name they had at the start of the log; a table that first appears under
        a new name keeps that name as its id.
        """
        events = []
        for d in self.ddl:
            at = self.committed_at(d["txn"])
            if at is not None:
                events.append((at, d["statements"]))
        events.sort(key=lambda x: x[0])
        names = {}   # current name -> physical id
        eras = []
        cur_start = pd.Timestamp.min.tz_localize("UTC")

        def phys(n):
            return names.get(n, n)

        current = phys(name)
        for at, stmts in events:
            new = dict(names)
            for st in stmts:
                m = _RENAME.search(st)
                if m:
                    old, nw = m.groups()
                    pid = new.pop(old, old)
                    new[nw] = pid
                    continue
                m = _DROP.search(st)
                if m:
                    new.pop(m.group(1), None)
                    new[m.group(1)] = None
            names = {k: v for k, v in new.items()}
            p = names.get(name, name)
            if p != current:
                eras.append((cur_start, at, current))
                cur_start, current = at, p
        eras.append((cur_start, pd.Timestamp.max.tz_localize("UTC"), current))
        # map "into <name>" at time t to physical id
        self._ddl_events = events
        return eras

    def physical_at(self, tname, at):
        """Physical id of the table named `tname` at time `at` (from committed DDL before `at`)."""
        names = {}
        for t, stmts in self._ddl_events:
            if t >= at:
                break
            for st in stmts:
                m = _RENAME.search(st)
                if m:
                    old, nw = m.groups()
                    names[nw] = names.pop(old, old)
                    continue
                m = _DROP.search(st)
                if m:
                    names[m.group(1)] = None
        return names.get(tname, tname)

